package com.travelmate.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;
@Component public class JwtFilter extends OncePerRequestFilter{private final JwtService jwt;private final UserDetailsService uds;public JwtFilter(JwtService jwt,UserDetailsService uds){this.jwt=jwt;this.uds=uds;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain f)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String email=jwt.extractEmail(h.substring(7));var u=uds.loadUserByUsername(email);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities()));}catch(Exception ignored){}f.doFilter(r,s);}}
